use vstd::prelude::*;

verus! {

spec fn vec_product(a: Seq<u32>, b: Seq<u32>) -> Seq<u32>
    requires
        a.len() == b.len(),
    decreases a.len(),
{
    Seq::new(a.len(), |i: int| a[i] * b[i])
}

fn product(a: &Vec<u32>, b: &Vec<u32>) -> (c: Vec<u32>)
    requires
        a@.len() == b@.len(),
        a@.len() <= 100,
    ensures
        c@ == vec_product(a@, b@),
        c@.len() == a@.len(),
{
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    assert!(a.len() <= 100, "Length must be at most 100");

    let mut c: Vec<u32> = Vec::with_capacity(a.len());
    for i in 0..a.len()
        invariant
            a@.len() == b@.len(),
            a@.len() <= 100,
            c@.len() == i as nat,
            c@ == vec_product(a@.subrange(0, i as int), b@.subrange(0, i as int)),
        decreases (a.len() - i),
    {
        c.push(a[i] * b[i]);

        // Help the solver connect "push" with the spec view of the vector
        assert(c@.len() == (i + 1) as nat);
        assert(c@ == vec_product(a@.subrange(0, (i + 1) as int), b@.subrange(0, (i + 1) as int)));
    }
    c
}

} // verus!

